<?php
namespace App\Jobs;use App\Models\NotificationOutboxEvent;use App\Services\NotificationOutboxService;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;
final class ProcessNotificationOutboxEvent implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=5;public int $timeout=30;public function __construct(public readonly int $eventId){}public function backoff():array{return[30,120,600,600];}public function handle(NotificationOutboxService $outbox):void{$event=NotificationOutboxEvent::find($this->eventId);if(!$event||$event->processed_at||$event->failed_at)return;try{$outbox->process($event);}catch(\Throwable $error){$outbox->markRetry($event,$error);throw $error;}}}
